using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.Data.Sqlite;
namespace GraficaCaixa;
// A closed set of business commands. Arguments are decoded into one concrete DTO;
// no property patch, client lambda, AppData or executable model input is accepted.
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record BusinessCommand(Guid OperationId,string Action,Guid EntityId,string? ExpectedRevision,JsonElement Arguments);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record CashOpenArgs(decimal Amount);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record SaleSaveArgs(Sale Sale,Guid? ClosedSessionId=null,string Reason="");
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record ReasonArgs(string Reason);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record RefundArgs(decimal Amount,string Method,string Reason);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record CashCloseArgs(decimal Amount);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record CashValuesArgs(decimal OpeningAmount,decimal ClosingAmount,DateTime OpenedAt,DateTime ClosedAt,string OpenedBy,string ClosedBy,string Reason);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record WithdrawalArgs(CashWithdrawal Withdrawal);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record CashAdjustmentArgs(CashAdjustment Adjustment);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record OrderDeliveryArgs(long ExpectedRevision,List<PaymentPart> Payments,DateTime PaidAt,bool KeepReceivable);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record OrderArchiveArgs(long ExpectedRevision,bool Restore,string Reason="");
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record OrderCostArgs(long ExpectedRevision,bool ItemCostsEnabled,bool IgnoreCosts,decimal? FreightCost,decimal? AdditionalCost,string CostNotes,string Reason,List<OrderItemCostArgs> Items){
    public static OrderCostArgs FromOrder(ScheduledOrder order)=>new(order.Revision,order.ItemCostsEnabled,order.IgnoreCosts,order.FreightCost,order.AdditionalCost,order.CostNotes,order.CostChangeReason,order.Items.Select(x=>new OrderItemCostArgs(x.Id,x.UnitCost,x.EnteredTotalCost,x.CostReviewed,x.CostIgnored,x.CostSource)).ToList());
}
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record OrderItemCostArgs(Guid Id,decimal? UnitCost,decimal? EnteredTotalCost,bool CostReviewed,bool CostIgnored,string CostSource);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record CustomerLinkArgs(long ExpectedRevision,Guid CustomerId,string CustomerRevision);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record CategoryArgs(string Name);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record PurchaseCompleteArgs(Purchase Purchase);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record SupplierArgs(Supplier Supplier);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record DebtSaveArgs(ManualDebt Debt);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record DebtReceiveArgs(List<PaymentPart> Payments,DateTime PaidAt);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record ProspectSaveArgs(Prospect Prospect);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record ProspectConvertArgs(ScheduledOrder Order);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record CollectionArgs(CollectionContact Contact);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record LossReopenArgs(string ReceivableRevision);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record LossDeclareArgs(decimal Balance,string Reason,DateTime Date,string Notes);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record LostSaveArgs(LostEntry Entry);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record FiscalArgs(FiscalDocument Document);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record ReworkArgs(OrderRework Rework);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record OutsourcedArgs(OutsourcedService Service);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record OrderExtraArgs(Guid Id);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record SettingsArgs(string DocumentsRoot,string LogoPath,Dictionary<string,decimal> PaymentRates,CompanyProfile? Company=null,BackupSchedule? Backup=null);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record DocumentRootArgs(string DocumentsRoot);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record BudgetArgs(List<BudgetRule> Rules);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record CalculatorArgs(string Settings);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record RulesArgs(BusinessRules Rules);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record TemplateArgs(CommunicationTemplate Template);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record DeadlineArgs(ProductionDeadline Deadline);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record ExpenseArgs(Expense Expense);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record EmptyArgs;
// Tipo de preço do cliente (Balcão = "", Revenda, Empresa): muda o preço dos próximos lançamentos e pedidos, por isso exige também alterar preços.
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record CustomerPriceTypeArgs(string PriceType);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record CustomerPurgeArgs(int ExpectedCount);
// Mesclar: EntityId = cadastro que fica; Remove = os do mesmo telefone que saem.
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record CustomerMergeArgs(List<Guid> Remove);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record ReceiptArgs(StandaloneReceipt Receipt,Guid? CustomerId=null,string? CustomerRevision=null);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record OrderPdfItem(Guid Id,long ExpectedRevision);
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)] public sealed record OrderPdfArgs(List<OrderPdfItem> Orders);
public sealed partial class DataStore
{
    static readonly JsonSerializerOptions BusinessJson=new(){UnmappedMemberHandling=JsonUnmappedMemberHandling.Disallow};
    static T Decode<T>(BusinessCommand c){try{return c.Arguments.Deserialize<T>(BusinessJson)??throw new WebRequestException(400,"Comando incompleto.");}catch(JsonException){throw new WebRequestException(400,"Campos inválidos para esta operação.");}}
    internal static string[] BusinessPermissions(string action)=>action switch {
        "receipt.create"=>["finance.receipt"],"order.pdf"=>["view.orders"],"cash.open"=>["view.cash","cash.open"],"cash.close"=>["view.cash","cash.close"],"cash.values"=>["view.closed","cash.rectify"],"cash.withdraw"=>["view.cash","cash.withdraw"],"cash.adjust"=>["view.cash","cash.adjust"],
        "sale.add"=>["finance.receive"],"sale.edit"=>[],"sale.cancel"=>["finance.correct","finance.reverse"],"sale.refund"=>["view.cash","finance.correct","finance.reverse"],
        "order.deliver"=>["view.orders","orders.deliver"],"order.archive" or "order.cancel"=>["view.orders","orders.cancel"],"order.link"=>["view.orders","orders.edit"],"order.cost"=>["view.orders","costs.edit"],
        "product.delete" or "product.category" or "product.classify"=>["view.products","products.edit"],
        "purchase.complete" or "purchase.reopen" or "purchase.delete"=>["view.purchases","purchases.edit"],"supplier.save"=>["view.purchases","purchases.edit"],
        "customer.delete" or "customer.purge"=>["view.customers","customers.edit"],"customer.merge"=>["view.customers","customers.edit","orders.edit"],"customer.pricetype"=>["view.customers","customers.edit","products.edit"],
        "debt.save" or "debt.delete"=>["view.debtors","debtors.edit"],"debt.receive"=>["view.debtors","view.cash","finance.receive"],"collection.save"=>["view.debtors","debtors.edit"],
        "prospect.save" or "prospect.contact"=>["view.prospects","prospects.edit"],"prospect.convert"=>["view.prospects","prospects.edit","view.orders","orders.create"],
        "loss.declare" or "loss.reopen"=>["view.debtors","system.owner"],"lost.add" or "lost.edit" or "lost.delete"=>["view.cash","finance.correct"],
        "fiscal.register"=>["view.orders","system.owner"],"rework.save" or "rework.delete" or "outsourced.save" or "outsourced.return" or "outsourced.delete"=>["view.orders","orders.edit"],"settings.save" or "settings.documents" or "template.save" or "rules.save"=>["system.settings"],
        "budget.save" or "deadline.save" or "calculator.save"=>["view.budget","budget.edit"],"expense.add" or "expense.edit" or "expense.pay" or "expense.deactivate"=>["system.owner"],
        _=>throw new WebRequestException(404,"Comando inexistente.")};
    void BusinessAuthorize(SqliteConnection db,UserIdentity actor,Dictionary<string,bool> p,BusinessCommand c){
        MobileAccess.Require(p,BusinessPermissions(c.Action));
        if(c.Action is "sale.add" or "sale.edit" or "sale.cancel" or "sale.refund"){
            Guid? closed=c.Action=="sale.add"?Decode<SaleSaveArgs>(c).ClosedSessionId:null;
            var session=ReadUnsafe(db,includeAudit:false).Sessions.FirstOrDefault(x=>closed.HasValue?x.Id==closed:x.Sales.Any(s=>s.Id==c.EntityId));
            MobileAccess.Require(p,closed.HasValue||session?.IsOpen==false?"view.closed":"view.cash");
        }
        if(c.Action=="receipt.create"&&Decode<ReceiptArgs>(c).CustomerId!=null)MobileAccess.Require(p,"view.customers","customers.edit");
        if(c.Action is "loss.declare" or "loss.reopen" || c.Action.StartsWith("expense.")){
            using var q=WebQueries.Command(db,"SELECT owner_until FROM auth_sessions WHERE id=@s",("@s",actor.SessionId));
            if(Convert.ToInt64(q.ExecuteScalar())<=DateTimeOffset.UtcNow.ToUnixTimeSeconds())throw new UnauthorizedAccessException("Entre novamente na área do proprietário.");
        }
    }
    public DesktopWriteResult BusinessExecute(UserIdentity actor,BusinessCommand c){
        JsonElement? value=null;object? resultValue=null;Guid[] changed=[];BusinessArtifact? artifact=null;Action<AppData>? finalAudit=null;
        try{return DesktopExecute(actor,c.OperationId,"business",c,(d,p)=>{
            var user=new OperationContext(actor.Name,actor.Role){Permissions=p};
            void Expected(object? x)=>DesktopExpected(x,c.ExpectedRevision);
            Sale Sale()=>d.Sessions.SelectMany(x=>x.Sales).FirstOrDefault(x=>x.Id==c.EntityId)??throw new WebRequestException(404,"Lançamento removido.");
            CashSession Session()=>d.Sessions.FirstOrDefault(x=>x.Id==c.EntityId)??throw new WebRequestException(404,"Caixa removido.");
            ScheduledOrder Order()=>d.ScheduledOrders.FirstOrDefault(x=>x.Id==c.EntityId)??throw new WebRequestException(404,"Pedido removido.");
            Prospect Prospect()=>d.Prospects.FirstOrDefault(x=>x.Id==c.EntityId)??throw new WebRequestException(404,"Acompanhamento removido.");
            void Audit(string action,string type,Guid id,string before,string after,string reason="",string description="")=>AuditService.Record(d,user,action,type,id.ToString(),before,after,reason,description);
            switch(c.Action){
            case "cash.open": {var a=Decode<CashOpenArgs>(c);Expected(d.Sessions.LastOrDefault(x=>x.IsOpen));resultValue=FinancialOperations.OpenCash(d,a.Amount,user);break;}
            case "sale.add": {var a=Decode<SaleSaveArgs>(c);if(a.ClosedSessionId is Guid id){Expected(d.Sessions.Single(x=>x.Id==id));MobileAccess.Require(p,"view.closed","cash.rectify");}else Expected(d.Sessions.LastOrDefault(x=>x.IsOpen));resultValue=FinancialOperations.AddSale(d,a.Sale,user,a.ClosedSessionId,a.Reason);break;}
            case "sale.edit": {var a=Decode<SaleSaveArgs>(c);var old=Sale();Expected(old);FinancialOperations.EditSale(d,old,a.Sale,a.Reason,user);break;}
            case "sale.cancel": {var a=Decode<ReasonArgs>(c);Expected(Sale());FinancialOperations.CancelSale(d,c.EntityId,a.Reason,user);break;}
            case "sale.refund": {var a=Decode<RefundArgs>(c);Expected(Sale());resultValue=FinancialOperations.RefundSale(d,c.EntityId,a.Amount,a.Method,a.Reason,user);break;}
            case "cash.close": {var a=Decode<CashCloseArgs>(c);var current=Session();Expected(current);resultValue=FinancialOperations.CloseCash(d,c.EntityId,current,a.Amount,user);break;}
            case "cash.values": {var a=Decode<CashValuesArgs>(c);var current=Session();Expected(current);FinancialOperations.RectifySessionValues(d,c.EntityId,current,a.OpeningAmount,a.ClosingAmount,a.OpenedAt,a.ClosedAt,a.OpenedBy,a.ClosedBy,a.Reason,user);break;}
            case "cash.withdraw": {var a=Decode<WithdrawalArgs>(c);Expected(Session());CashOperations.Withdraw(d,c.EntityId,a.Withdrawal,user);break;}
            case "cash.adjust": {var a=Decode<CashAdjustmentArgs>(c);Expected(Session());CashOperations.Adjust(d,c.EntityId,a.Adjustment,user);break;}
            case "order.deliver": {var a=Decode<OrderDeliveryArgs>(c);var order=MobileFind(d,c.EntityId,a.ExpectedRevision);if(a.Payments.Count>0){MobileAccess.Require(p,"view.cash","finance.receive");OrderOperations.AddPayments(d,order,a.Payments,a.PaidAt,user);}OrderOperations.AdvanceStage(d,c.EntityId,order.Revision,"Entregue",user,a.KeepReceivable);break;}
            case "order.archive": {var a=Decode<OrderArchiveArgs>(c);var order=MobileFind(d,c.EntityId,a.ExpectedRevision);if(order.IsCancelled)throw new WebRequestException(422,"Pedido cancelado não pode ser arquivado nem restaurado.");order.Revision++;order.IsUncollected=!a.Restore;order.ArchivedAsUncollectedAt=a.Restore?null:DateTime.Now;Audit(a.Restore?"Pedido restaurado":"Pedido arquivado","Pedido",order.Id,a.Restore?"Arquivado":"Ativo",a.Restore?"Ativo":"Arquivado",a.Reason,$"Pedido #{order.Number}");break;}
            // Cancelar (≠ arquivar): pedido sai de tudo (inclusive Arquivados) e não conta em faturamento nem em a receber. Exige motivo e nada recebido.
            case "order.cancel": {var a=Decode<OrderArchiveArgs>(c);var order=MobileFind(d,c.EntityId,a.ExpectedRevision);try{OrderOperations.Cancel(order,a.Reason,user.UserName);}catch(InvalidOperationException ex){throw new WebRequestException(422,ex.Message);}Audit("Pedido cancelado","Pedido",order.Id,order.IsUncollected?"Arquivado":"Ativo","Cancelado",a.Reason,$"Pedido #{order.Number}");break;}
            case "order.cost": {var a=Decode<OrderCostArgs>(c);var old=Order();if(old.Revision!=a.ExpectedRevision)throw new WebRequestException(409,"Pedido alterado.");
                if(a.Items.Count!=old.Items.Count||a.Items.Select(x=>x.Id).Distinct().Count()!=a.Items.Count||a.Items.Any(x=>old.Items.All(y=>y.Id!=x.Id)))throw new WebRequestException(409,"Os itens mudaram. Reabra o pedido.");
                var draft=JsonSerializer.Deserialize<ScheduledOrder>(JsonSerializer.Serialize(old))!;draft.ItemCostsEnabled=a.ItemCostsEnabled;draft.IgnoreCosts=a.IgnoreCosts;draft.FreightCost=a.FreightCost;draft.AdditionalCost=a.AdditionalCost;draft.CostNotes=a.CostNotes;draft.CostChangeReason=a.Reason;
                foreach(var item in draft.Items){var cost=a.Items.Single(x=>x.Id==item.Id);item.UnitCost=cost.UnitCost;item.EnteredTotalCost=cost.EnteredTotalCost;item.CostReviewed=cost.CostReviewed;item.CostIgnored=cost.CostIgnored;item.CostSource=cost.CostSource;}OrderOperations.SaveCosts(d,draft,user);break;}
            case "order.link": {var a=Decode<CustomerLinkArgs>(c);var order=MobileFind(d,c.EntityId,a.ExpectedRevision);var customer=d.Customers.Single(x=>x.Id==a.CustomerId);DesktopExpected(customer,a.CustomerRevision);var before=order.CustomerName;order.CustomerId=customer.Id;order.CustomerName=customer.Name;order.Contact=customer.Contact;order.Revision++;var ids=order.Payments.Where(x=>x.SaleId.HasValue).Select(x=>x.SaleId!.Value).Append(order.DepositSaleId??Guid.Empty).Append(order.FinalSaleId??Guid.Empty).ToHashSet();foreach(var sale in d.Sessions.SelectMany(x=>x.Sales).Where(x=>ids.Contains(x.Id))){sale.CustomerName=customer.Name;sale.Contact=customer.Contact;}Audit("Cliente vinculado ao pedido","Pedido",order.Id,before,customer.Name,"",$"Pedido #{order.Number}");resultValue=order.Revision;break;}
            case "product.delete": {Decode<EmptyArgs>(c);var old=d.Products.Single(x=>x.Id==c.EntityId);var visible=BusinessVisibleProduct(old,p);Expected(visible);ProductOperations.Delete(d,old,user);break;}
            case "product.category": {var a=Decode<CategoryArgs>(c);resultValue=ProductOperations.CreateCategory(d,a.Name,user);break;}
            case "product.classify": {Decode<EmptyArgs>(c);var count=ProductOperations.FillMissingCategories(d.Products);if(count>0)Audit("Categorias de produtos preenchidas","Produto",Guid.Empty,"",count.ToString(),"Somente categorias vazias",$"{count} produto(s) classificados; casos incertos marcados para Revisar.");resultValue=count;break;}
            case "purchase.complete": case "purchase.reopen": case "purchase.delete": {var need=d.Prompt12.PurchaseNeeds.Single(x=>x.Id==c.EntityId);Expected(need);if(c.Action=="purchase.complete"){var a=Decode<PurchaseCompleteArgs>(c);if(need.Status!=PurchaseNeedStatus.ToBuy)throw new WebRequestException(409,"Compra já concluída.");if(a.Purchase.NeedId!=need.Id)throw new WebRequestException(400,"Compra inválida.");if(a.Purchase.SupplierId is Guid sid&&!d.Prompt12.Suppliers.Any(x=>x.Id==sid))a.Purchase.SupplierId=null;need.Status=PurchaseNeedStatus.Received;d.Prompt12.Purchases.Add(a.Purchase);Audit("Compra concluída","Compra",need.Id,"ToBuy","Received","",need.Material);}else{Decode<EmptyArgs>(c);if(c.Action=="purchase.reopen"){var before=need.Status;need.Status=PurchaseNeedStatus.ToBuy;d.Prompt12.Purchases.RemoveAll(x=>x.NeedId==need.Id);Audit("Compra reaberta","Compra",need.Id,before.ToString(),"ToBuy","",need.Material);}else{d.Prompt12.PurchaseNeeds.Remove(need);Audit("Necessidade de compra excluída","Compra",need.Id,need.Material,"","Exclusão confirmada",need.RequestedBy);}}break;}
            case "supplier.save": {var a=Decode<SupplierArgs>(c);if(a.Supplier.Id!=c.EntityId)throw new WebRequestException(400,"Identidade inválida.");Expected(d.Prompt12.Suppliers.FirstOrDefault(x=>x.Id==c.EntityId));(string Before,string After) text;try{text=SupplierBook.Save(d.Prompt12,a.Supplier);}catch(InvalidOperationException ex){throw new WebRequestException(422,ex.Message);}Audit(text.Before.Length==0?"Fornecedor cadastrado":"Fornecedor alterado","Fornecedor",a.Supplier.Id,text.Before,text.After,"",a.Supplier.Name);break;}
            case "debt.save": {var a=Decode<DebtSaveArgs>(c);if(a.Debt.Id!=c.EntityId)throw new WebRequestException(400,"Identidade inválida.");var old=d.ManualDebts.FirstOrDefault(x=>x.Id==c.EntityId);Expected(old);if(old!=null){if(a.Debt.Amount<old.Paid(d))throw new InvalidOperationException("O total não pode ser menor que o valor já recebido.");d.ManualDebts.Remove(old);}ReceivableViews.Link(d,a.Debt);d.ManualDebts.Add(a.Debt);if(a.Debt.Remaining(d)>0&&(old==null||old.InitialCollectionStatus!=a.Debt.InitialCollectionStatus))CollectionControl.Register(d,new CollectionContact{DebtId=a.Debt.Id,IsOrder=false,Status=a.Debt.InitialCollectionStatus,Notes="Status informado no cadastro da dívida."});break;}
            case "customer.pricetype": {var a=Decode<CustomerPriceTypeArgs>(c);var type=(a.PriceType??"").Trim();if(type.Length>0&&!BusinessRules.PriceTypes.Contains(type))throw new WebRequestException(422,"Tipo de cliente inválido.");var customer=d.Customers.FirstOrDefault(x=>x.Id==c.EntityId)??throw new WebRequestException(404,"Cliente removido.");Expected(customer);var before=customer.PriceType.Length==0?"Balcão":customer.PriceType;customer.PriceType=type;customer.UpdatedAt=DateTime.Now;Audit("Tipo de preço do cliente alterado","Cliente",customer.Id,before,type.Length==0?"Balcão":type,"",customer.Name);break;}
            case "customer.delete": {Decode<EmptyArgs>(c);var customer=d.Customers.FirstOrDefault(x=>x.Id==c.EntityId)??throw new WebRequestException(404,"Cliente removido.");Expected(customer);CustomerBasicOperations.Delete(d,c.EntityId,user);break;}
            case "customer.purge": {var a=Decode<CustomerPurgeArgs>(c);resultValue=CustomerBasicOperations.DeleteWithoutFullPhone(d,a.ExpectedCount,user);break;}
            case "customer.merge": {var a=Decode<CustomerMergeArgs>(c);var keep=d.Customers.FirstOrDefault(x=>x.Id==c.EntityId)??throw new WebRequestException(404,"Cliente removido.");Expected(keep);CustomerBasicOperations.Merge(d,c.EntityId,a.Remove,user);break;}
            case "debt.delete": {Decode<EmptyArgs>(c);var deleted=RemoveManualDebt(d,c.EntityId,c.ExpectedRevision,user);var before=JsonSerializer.Serialize(deleted);
                finalAudit=next=>next.AuditTrail.Add(new AuditEntry{Id=c.OperationId,Timestamp=DateTime.UtcNow,UserId=actor.UserId.ToString(),UserLogin=actor.Login,SessionId=actor.SessionId.ToString(),UserName=actor.Name,Computer="Servidor / dispositivo "+actor.DeviceId,Action="Dívida avulsa excluída",EntityType="Dívida avulsa",EntityId=c.EntityId.ToString(),OldValue=before,Reason="Exclusão confirmada de lançamento avulso incorreto",Description=$"{deleted.CustomerName} • {deleted.Description} • {deleted.Amount:C2}"});break;}
            case "debt.receive": {var a=Decode<DebtReceiveArgs>(c);var debt=d.ManualDebts.Single(x=>x.Id==c.EntityId);Expected(debt);var before=debt.Remaining(d);var parts=a.Payments.Where(x=>!debt.SaleIds.Contains(x.Id)).ToList();PaymentPolicy.Validate(parts,before);foreach(var part in parts){FinancialOperations.AddSale(d,new Sale{Id=part.Id,CreatedAt=part.PaidAt??a.PaidAt,CustomerName=debt.CustomerName,Contact=debt.Contact,Product=$"Recebimento avulso: {debt.Description}",Units=1,TotalValue=part.Amount,PaymentType=part.PaymentType,FeePercent=part.FeePercent??PaymentPolicy.Rate(part.PaymentType)},user);debt.SaleIds.Add(part.Id);}Audit("Dívida recebida","Conta a receber",debt.Id,before.ToString("0.00"),debt.Remaining(d).ToString("0.00"));break;}
            case "prospect.save": {var a=Decode<ProspectSaveArgs>(c);if(a.Prospect.Id!=c.EntityId)throw new WebRequestException(400,"Identidade inválida.");if(a.Prospect.Amount is <0 or >100_000_000)throw new WebRequestException(422,"Valor do orçamento inválido.");var old=d.Prospects.FirstOrDefault(x=>x.Id==c.EntityId);Expected(old);if(old!=null)d.Prospects.Remove(old);d.Prospects.Add(a.Prospect);break;}
            case "prospect.contact": {Decode<EmptyArgs>(c);var prospect=Prospect();Expected(prospect);if(prospect.OrderId!=null||prospect.Status=="Não fechou")throw new InvalidOperationException("Este acompanhamento já foi encerrado.");prospect.LastContactAt=DateTime.Now;prospect.Notes+=$"\nContato realizado em {DateTime.Now:dd/MM/yyyy HH:mm}";prospect.NextContactAt=DateTime.Today.AddDays(BusinessRules.Current.FollowUpDays);break;}
            case "prospect.convert": {var a=Decode<ProspectConvertArgs>(c);var prospect=Prospect();Expected(prospect);if(prospect.OrderId!=null)throw new WebRequestException(409,"Já convertido.");changed=OrderOperations.Save(d,a.Order,user).ToArray();prospect.OrderId=a.Order.Id;prospect.Status="Convertido em pedido";prospect.NextContactAt=null;break;}
            case "collection.save": {var a=Decode<CollectionArgs>(c);if(a.Contact.DebtId!=c.EntityId)throw new WebRequestException(400,"Conta inválida.");Expected(a.Contact.IsOrder?(object)Order():d.ManualDebts.Single(x=>x.Id==c.EntityId));CollectionControl.Register(d,a.Contact);break;}
            case "loss.reopen": {var a=Decode<LossReopenArgs>(c);var loss=d.Prompt12.Losses.SingleOrDefault(x=>x.Id==c.EntityId)??throw new WebRequestException(404,"Perda removida.");Expected(loss);var origin=(object?)d.ScheduledOrders.FirstOrDefault(x=>x.Id==loss.OrderId)??d.ManualDebts.FirstOrDefault(x=>x.Id==loss.OrderId)??throw new WebRequestException(404,"Origem removida.");DesktopExpected(origin,a.ReceivableRevision);var before=JsonSerializer.Serialize(loss);LossOperations.Reopen(d,loss.Id,user);var after=JsonSerializer.Serialize(loss);finalAudit=data=>data.AuditTrail.Add(new(){Id=c.OperationId,Timestamp=DateTime.UtcNow,UserId=actor.UserId.ToString(),UserLogin=actor.Login,SessionId=actor.SessionId.ToString(),UserName=actor.Name,Computer="Servidor",EntityType="Perda",EntityId=loss.Id.ToString(),Action="Cobrança reaberta",Description=$"Origem {loss.OrderId}; recebimento separado pelo fluxo normal",OldValue=before,NewValue=after,Reason="Recuperar perda: reabrir cobrança"});break;}
