            case "settings.save": {var a=Decode<SettingsArgs>(c);Expected(new SettingsArgs(d.DocumentsRoot,d.LogoPath,d.PaymentRates,d.Company,d.Backup));if(a.Backup is {} backup){if(backup.Mode is not ("intervalo" or "diario" or "semanal")||backup.IntervalHours is <1 or >168||backup.KeepCopies is <1 or >365||!TimeSpan.TryParseExact(backup.Time,@"hh\:mm",System.Globalization.CultureInfo.InvariantCulture,out _)||backup.Days.Any(x=>x is <0 or >6)||backup.Mode=="semanal"&&backup.Days.Count==0)throw new WebRequestException(422,"Confira o agendamento do backup (frequência, horário, dias e quantidade de cópias).");if(backup.Enabled||backup.Destination.Length>0){try{BackupScheduler.ValidateDestination(backup.Destination);}catch(InvalidOperationException ex){throw new WebRequestException(422,ex.Message);}}}if(a.Company is {} company&&(string.IsNullOrWhiteSpace(company.Name)||company.Name.Length>120||new[]{company.Document,company.Address,company.Phone,company.Email,company.City,company.StampPath,company.PixKey}.Any(x=>(x??"").Length>200)||(company.ReviewUrl??"").Length>300||(company.OpeningHours??"").Length>300||(company.ReviewUrl??"").Trim().Length>0&&OrderTracking.ReviewLink(company.ReviewUrl)==null))throw new WebRequestException(422,"Confira os dados da gráfica: o nome é obrigatório.");d.DocumentsRoot=a.DocumentsRoot;d.LogoPath=a.LogoPath;d.PaymentRates=a.PaymentRates;if(a.Company!=null)d.Company=a.Company;if(a.Backup!=null)d.Backup=a.Backup;break;}
