            case "deadline.save": {var a=Decode<DeadlineArgs>(c);var row=a.Deadline;if(row.Id!=c.EntityId)throw new WebRequestException(400,"Identidade inválida.");d.ProductionDeadlines??=ProductionDeadlineDefaults.Create();var old=d.ProductionDeadlines.FirstOrDefault(x=>x.Id==c.EntityId);Expected(old);row.Order=old?.Order??checked(d.ProductionDeadlines.Select(x=>x.Order).DefaultIfEmpty(0).Max()+10);row.Revision=(old?.Revision??0)+1;if(old!=null)d.ProductionDeadlines.Remove(old);d.ProductionDeadlines.Add(row);break;}
            case "expense.add": case "expense.edit": case "expense.pay": case "expense.deactivate": {var old=d.Prompt12.Expenses.FirstOrDefault(x=>x.Id==c.EntityId);Expected(old);if(c.Action=="expense.add"){var a=Decode<ExpenseArgs>(c);if(old!=null||a.Expense.Id!=c.EntityId)throw new WebRequestException(409,"Despesa já existente.");PrivateFinance.AddExpense(d,a.Expense,new OwnerSession(TimeSpan.FromMinutes(1)),user);}else{if(old==null)throw new WebRequestException(404,"Despesa removida.");if(c.Action=="expense.edit"){var a=Decode<ExpenseArgs>(c);a.Expense.Id=old.Id;a.Expense.Status=old.Status;a.Expense.PaidAt=old.PaidAt;a.Expense.Active=old.Active;d.Prompt12.Expenses[d.Prompt12.Expenses.IndexOf(old)]=a.Expense;}else{Decode<EmptyArgs>(c);if(!old.Active||old.Status==ExpenseStatus.Paid)throw new WebRequestException(409,"Despesa já paga ou inativa.");if(c.Action=="expense.pay"){old.Status=ExpenseStatus.Paid;old.PaidAt=DateTime.Now;}else old.Active=false;}}break;}
