    public static ManualDebt RemoveManualDebt(AppData data,Guid id,string? expectedRevision,OperationContext user){
        var debt=data.ManualDebts.FirstOrDefault(x=>x.Id==id)??throw new InvalidOperationException("Dívida avulsa não encontrada. Atualize a lista.");
        DesktopExpected(debt,expectedRevision);
        if(debt.SaleIds.Count>0)throw new InvalidOperationException("Esta dívida possui recebimentos registrados e não pode ser excluída.");
        if(data.Prompt12.Losses.Any(x=>x.OrderId==id))throw new InvalidOperationException("Esta dívida possui perda registrada e não pode ser excluída.");
        data.ManualDebts.Remove(debt);
        AuditService.Record(data,user,"Dívida avulsa excluída","Dívida avulsa",id.ToString(),JsonSerializer.Serialize(debt),"","Exclusão confirmada de lançamento avulso incorreto",$"{debt.CustomerName} • {debt.Description} • {debt.Amount:C2}");
        return debt;
    }
    static Product BusinessVisibleProduct(Product source,IReadOnlyDictionary<string,bool> p){var copy=JsonSerializer.Deserialize<Product>(JsonSerializer.Serialize(source))!;if(!p.GetValueOrDefault("costs.edit")){copy.Cost=null;foreach(var x in copy.ExactQuantityPrices)x.TotalCost=null;foreach(var x in copy.QuantityPriceTiers)x.UnitCost=null;}return copy;}
    public async Task<DesktopWriteResult> RemoteBusinessAsync(string action,Guid id,string? expected,object args,CancellationToken cancellation=default,Guid? operationId=null)=>
        await RemoteDesktopWriteAsync("desktop/business",new BusinessCommand(operationId??Guid.NewGuid(),action,id,expected,JsonSerializer.SerializeToElement(args)),cancellation).ConfigureAwait(false);
    public Task<DesktopWriteResult> RemoteDesktopWriteAsync(string path,object command,CancellationToken cancellation=default)=>remote?.DesktopWriteAsync(path,command,cancellation)??throw new InvalidOperationException("Comando remoto exige conexão.");
